CREATE OR REPLACE FUNCTION public.kf_submit_move(p_game_id uuid, p_fen text, p_pgn text, p_turn text, p_last_move jsonb, p_status text, p_result text, p_winner_id uuid, p_client_white_time integer, p_client_black_time integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
                      DECLARE
                        g public.kf_games%ROWTYPE;
                          v_expected_turn text;
                            v_now timestamptz := clock_timestamp();
                              v_anchor timestamptz;
                                v_elapsed numeric(12,3);
                                  v_moving_time numeric(12,3);
                                    v_white numeric(12,3);
                                      v_black numeric(12,3);
                                        v_result text;
                                          v_winner uuid;
                                            v_status text;
                                              v_absence jsonb;
                                              BEGIN
                                                IF auth.uid() IS NULL THEN
                                                    RAISE EXCEPTION 'Please sign in first';
                                                      END IF;

                                                        IF p_turn NOT IN ('w','b') THEN
                                                            RAISE EXCEPTION 'Invalid turn';
                                                              END IF;

                                                                IF p_status NOT IN ('active','completed') THEN
                                                                    RAISE EXCEPTION 'Invalid game status';
                                                                      END IF;

                                                                        IF p_fen IS NULL OR p_pgn IS NULL OR p_last_move IS NULL THEN
                                                                            RAISE EXCEPTION 'Missing move data';
                                                                              END IF;

                                                                                v_expected_turn := CASE WHEN p_turn = 'b' THEN 'w' ELSE 'b' END;

                                                                                  SELECT *
                                                                                    INTO g
                                                                                      FROM public.kf_games
                                                                                        WHERE id = p_game_id
                                                                                          FOR UPDATE;

                                                                                            IF NOT FOUND THEN
                                                                                                RAISE EXCEPTION 'Game not found';
                                                                                                  END IF;

                                                                                                    IF auth.uid() NOT IN (g.white_id, g.black_id) THEN
                                                                                                        RAISE EXCEPTION 'You are not a player in this game';
                                                                                                          END IF;

                                                                                                            IF g.is_bloodblade IS TRUE AND ((v_expected_turn = 'w' AND g.white_handicap IS NULL) OR (v_expected_turn = 'b' AND g.black_handicap IS NULL)) THEN RAISE EXCEPTION 'Bloodblade requires sacrificing a piece before your first move'; END IF;
 IF g.status <> 'active' THEN
                                                                                                                RAISE EXCEPTION 'This game has finished';
                                                                                                                  END IF;

                                                                                                                    -- Check the 20-second absence rule before accepting a move.
                                                                                                                      IF g.last_move_at IS NULL
                                                                                                                           AND g.created_at IS NOT NULL
                                                                                                                                AND clock_timestamp() >= g.created_at + interval '20 seconds'
                                                                                                                                  THEN
                                                                                                                                      v_absence := public.kf_resolve_absent_game(p_game_id);

                                                                                                                                          IF COALESCE((v_absence->>'resolved')::boolean, false) THEN
                                                                                                                                                SELECT *
                                                                                                                                                      INTO g
                                                                                                                                                            FROM public.kf_games
                                                                                                                                                                  WHERE id = p_game_id;

                                                                                                                                                                        RETURN jsonb_build_object(
                                                                                                                                                                                'status', g.status,
                                                                                                                                                                                        'result', g.result,
                                                                                                                                                                                                'winner_id', g.winner_id,
                                                                                                                                                                                                        'white_time_left', g.white_time_left,
                                                                                                                                                                                                                'black_time_left', g.black_time_left,
                                                                                                                                                                                                                        'last_move_at', g.last_move_at,
                                                                                                                                                                                                                                'clock_started_at', g.clock_started_at
                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                          END IF;
                                                                                                                                                                                                                                            END IF;

                                                                                                                                                                                                                                              IF g.turn <> v_expected_turn THEN
                                                                                                                                                                                                                                                  RAISE EXCEPTION 'The game position has changed';
                                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                                      IF (v_expected_turn = 'w' AND auth.uid() <> g.white_id)
                                                                                                                                                                                                                                                           OR (v_expected_turn = 'b' AND auth.uid() <> g.black_id)
                                                                                                                                                                                                                                                             THEN
                                                                                                                                                                                                                                                                 RAISE EXCEPTION 'It is not your turn';
                                                                                                                                                                                                                                                                   END IF;

                                                                                                                                                                                                                                                                     IF g.is_roulette IS TRUE AND g.clock_started_at IS NOT NULL AND clock_timestamp() < g.clock_started_at THEN RAISE EXCEPTION 'Roulette opening animation is still running'; END IF; IF g.clock_started_at IS NULL THEN
                                                                                                                                                                                                                                                                         RAISE EXCEPTION 'Waiting for both players to be ready';
                                                                                                                                                                                                                                                                           END IF;

                                                                                                                                                                                                                                                                             v_anchor := COALESCE(g.last_move_at, g.clock_started_at);

                                                                                                                                                                                                                                                                               v_elapsed := GREATEST(
                                                                                                                                                                                                                                                                                   0,
                                                                                                                                                                                                                                                                                       extract(epoch FROM (v_now - v_anchor))::numeric
                                                                                                                                                                                                                                                                                         );

                                                                                                                                                                                                                                                                                           v_white := COALESCE(g.white_time_left, 300);
                                                                                                                                                                                                                                                                                             v_black := COALESCE(g.black_time_left, 300);

                                                                                                                                                                                                                                                                                               IF g.turn = 'w' THEN
                                                                                                                                                                                                                                                                                                   v_moving_time := v_white - v_elapsed;

                                                                                                                                                                                                                                                                                                       IF v_moving_time <= 0 THEN
                                                                                                                                                                                                                                                                                                             v_white := 0;
                                                                                                                                                                                                                                                                                                                   v_result := '0-1';
                                                                                                                                                                                                                                                                                                                         v_winner := g.black_id;
                                                                                                                                                                                                                                                                                                                               v_status := 'completed';
                                                                                                                                                                                                                                                                                                                                   ELSE
                                                                                                                                                                                                                                                                                                                                         v_white := v_moving_time;
                                                                                                                                                                                                                                                                                                                                               v_status := p_status;
                                                                                                                                                                                                                                                                                                                                                     v_result := p_result;
                                                                                                                                                                                                                                                                                                                                                           v_winner := p_winner_id;
                                                                                                                                                                                                                                                                                                                                                               END IF;
                                                                                                                                                                                                                                                                                                                                                                 ELSE
                                                                                                                                                                                                                                                                                                                                                                     v_moving_time := v_black - v_elapsed;

                                                                                                                                                                                                                                                                                                                                                                         IF v_moving_time <= 0 THEN
                                                                                                                                                                                                                                                                                                                                                                               v_black := 0;
                                                                                                                                                                                                                                                                                                                                                                                     v_result := '1-0';
                                                                                                                                                                                                                                                                                                                                                                                           v_winner := g.white_id;
                                                                                                                                                                                                                                                                                                                                                                                                 v_status := 'completed';
                                                                                                                                                                                                                                                                                                                                                                                                     ELSE
                                                                                                                                                                                                                                                                                                                                                                                                           v_black := v_moving_time;
                                                                                                                                                                                                                                                                                                                                                                                                                 v_status := p_status;
                                                                                                                                                                                                                                                                                                                                                                                                                       v_result := p_result;
                                                                                                                                                                                                                                                                                                                                                                                                                             v_winner := p_winner_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                 END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                   END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                     IF v_status = 'completed' THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                         IF v_result IS NULL OR v_result NOT IN ('1-0','0-1','1/2-1/2') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                               RAISE EXCEPTION 'Invalid result';
                                                                                                                                                                                                                                                                                                                                                                                                                                                   END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                       IF v_result = '1-0' AND v_winner IS DISTINCT FROM g.white_id THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                             RAISE EXCEPTION 'Invalid winner';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                     IF v_result = '0-1' AND v_winner IS DISTINCT FROM g.black_id THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           RAISE EXCEPTION 'Invalid winner';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   IF v_result = '1/2-1/2' AND v_winner IS NOT NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         RAISE EXCEPTION 'A draw cannot have a winner';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ELSE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   IF v_result IS NOT NULL OR v_winner IS NOT NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         RAISE EXCEPTION 'Active games cannot have a final result';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 UPDATE public.kf_games
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   SET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       fen = p_fen,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           pgn = p_pgn,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               turn = p_turn,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   last_move = p_last_move,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       status = v_status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           result = v_result,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               winner_id = v_winner,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   white_time_left = GREATEST(0, v_white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       black_time_left = GREATEST(0, v_black),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           last_move_at = v_now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               completed_at = CASE WHEN v_status = 'completed' THEN v_now ELSE NULL END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   updated_at = v_now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       draw_offer_by = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           draw_offer_status = NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               draw_offer_at = NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE id = p_game_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   IF v_status = 'completed' THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       DELETE FROM public.kf_match_queue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           WHERE user_id IN (g.white_id, g.black_id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               RETURN jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'status', v_status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'result', v_result,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'winner_id', v_winner,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               'white_time_left', GREATEST(0, v_white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'black_time_left', GREATEST(0, v_black),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'last_move_at', v_now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'clock_started_at', g.clock_started_at
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             END;
$function$;

